'use strict';
const Gameday=(()=>{
 const E=GamedayEngine,storeKey='darkhorse-tickets-v1',draftKey='darkhorse-betslip-v1';
 let slipTrigger=null,renderPool=null;
 const startedRequest=StartedGames.ready;
 let selectedDay=E.day(Date.now()),started=[],legs=[],saved=[],lensId=null,ready=false,storageOK=true,stake=10,showArchived=false,toastTimer;
 const signed=n=>n>0?'+'+n:String(n),money=n=>n==null?'—':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n);
 const fullDay=k=>new Date(k+'T12:00Z').toLocaleDateString('en-US',{timeZone:'UTC',weekday:'long',month:'long',day:'numeric'});
 function allRows(){
  const map=new Map(started.map(g=>[g.id,{...g,archived:true}]));
  for(const f of M.forecasts){const g=game(f);if(!map.has(g.id)){
   const row={...g,f};
   if(Date.parse(g.date)<=Date.now()&&Date.parse(M.generatedAt)<Date.parse(g.date)&&Date.parse(M.inputRetrievedAt)<Date.parse(g.date)){
    const m=meta(g),quoteOK=Date.parse(m.retrievedAt)<Date.parse(g.date);
    row.savedPick={homeMargin:f.coreMargin,total:f.coreTotal,forecastAt:M.generatedAt,quote:quoteOK?{homeSpread:m.homeSpread,overUnder:m.overUnder}:null};
   }
   map.set(g.id,row);
  }}
  for(const live of LiveScores.games){const row=map.get(live.id);if(row&&row.home===live.home&&row.away===live.away&&live.state!=='pre')map.set(live.id,{...row,...live});}
  return [...map.values()].sort((a,b)=>a.date.localeCompare(b.date));
 }
 function time(g){return g.timeValid===false?'Time TBA':new Date(g.date).toLocaleTimeString('en-US',{timeZone:'America/New_York',hour:'numeric',minute:'2-digit'});}
 function status(g){if(g.state==='in')return g.detail||'In progress';return g.done?'Final':/POSTPONED|CANCEL/.test(g.status||'')?StartedGames.state(g):Date.parse(g.date)<=Date.now()?'Started · score pending':time(g)+' ET';}
 function filtered(){const query=$('search').value.trim().toLowerCase(),conf=$('conference').value;const tier=$('gdTier')?.value||'all';return allRows().filter(g=>E.day(g.date)===selectedDay&&(tier==='all'||(()=>{const o=parlayOdds?.games[g.id],q=g.f?forecast(g.f):null,v=q?o?.[q.p>.5?'homeMoneyline':'awayMoneyline']:null;return Number.isFinite(v)&&(tier==='dogs'?v>0:tier==='seabiscuit'?v>=170:v<0);})())&&(conf==='all'||[g.home,g.away].some(t=>D.teams[t]?.conference===conf))&&(!query||[g.home,g.away].some(t=>[name(t),D.teams[t]?.abbr].some(v=>v?.toLowerCase().includes(query)))));}
 function quoteReady(o,g){return o&&o.state==='pre'&&!g.done&&Date.parse(g.date)>Date.now()&&E.available({odds:100,date:o.date,quoteAt:o.retrievedAt,timeValid:o.timeValid});}
 function pool(){
  if(renderPool)return renderPool;
  if(typeof parlayOdds==='undefined'||!parlayOdds||DartHealth.health(M).stale)return [];
  const rows=[];
  for(const f of M.forecasts){const g=game(f),o=parlayOdds.games[g.id];if(!o||!quoteReady(o,g)||f.reviewRequired)continue;const q=forecast(f),base={id:g.id,home:g.home,away:g.away,provider:o.provider,date:o.date,quoteAt:o.retrievedAt,timeValid:o.timeValid,reviewRequired:f.reviewRequired,runId:M.refreshRunId,modelAt:M.inputRetrievedAt};
   for(const side of ['away','home']){const team=g[side],win=side==='home'?q.p:1-q.p,odds=o[side+'Moneyline'];if(E.decimal(odds))rows.push({...base,team,market:'moneyline',p:win,odds});const line=o[side+'Spread'],price=o[side+'SpreadOdds'];if(Number.isFinite(line)&&E.decimal(price))rows.push({...base,team,market:'spread',line,odds:price,p:null,modelPick:(side==='home'?q.margin:-q.margin)+line>0});}
   if(Number.isFinite(o.total))for(const side of ['over','under'])if(E.decimal(o[side+'Odds']))rows.push({...base,team:g.home,market:'total',side,line:o.total,odds:o[side+'Odds'],p:null,modelPick:side==='over'?q.total>o.total:q.total<o.total});
  }return rows;
 }
 function legFor(id,team,market='moneyline',side){return pool().find(l=>l.id===id&&l.market===market&&(market==='total'?l.side===side:l.team===team));}
 function freshLeg(l){return legFor(l.id,l.team,l.market,l.side);}
 function legLabel(l){return l.market==='total'?(l.side==='over'?'Over ':'Under ')+l.line:l.market==='spread'?name(l.team)+' '+signed(l.line):name(l.team)+' to win';}
 function marketButton(l){const selected=legs.some(x=>E.key(x)===E.key(l)),label=legLabel(l);return `<button class="gd-market-price gd-price ${l.modelPick?'gd-picked':''} ${selected?'gd-in-ticket':''}" data-add-game="${esc(l.id)}" data-add-team="${esc(l.team)}" data-market="${l.market}" data-side="${l.side||''}" aria-pressed="${selected}" aria-label="${esc('Add '+label+' at '+signed(l.odds))}"><span>${esc(label)}</span><b>${signed(l.odds)}</b>${l.modelPick?'<small>MODEL PICK</small>':''}</button>`;}
 function marketRows(g){const rows=pool().filter(l=>l.id===g.id&&l.market!=='moneyline');return `<div class="gd-market-board"><small>SPREAD</small><small>OVER / UNDER</small><div>${rows.filter(l=>l.market==='spread').map(marketButton).join('')||'<span>Prices unavailable</span>'}</div><div>${rows.filter(l=>l.market==='total').map(marketButton).join('')||'<span>Prices unavailable</span>'}</div></div>`;}
 function matchOdds(){if(!current||!ready)return;const q=forecast(current),gm=game(current),m=meta(gm);let picks=$('gdReportPicks');if(!picks){picks=document.createElement('div');picks.id='gdReportPicks';picks.className='gd-picks-row';document.querySelector('.forecast .score').after(picks);}const cover=Number.isFinite(m.homeSpread)?q.margin+m.homeSpread:null;picks.innerHTML=`<div><small>MODEL COVER PICK</small><b>${cover===null||cover===0?'No pick':esc(name(cover>0?gm.home:gm.away))+' '+signed(cover>0?m.homeSpread:-m.homeSpread)}</b></div><div><small>MODEL O/U PICK</small><b>${!Number.isFinite(m.overUnder)||q.total===m.overUnder?'No pick':(q.total>m.overUnder?'Over ':'Under ')+m.overUnder}</b></div>`;const g=game(current);let mount=$('gdMatchOdds');if(!mount){mount=document.createElement('div');mount.id='gdMatchOdds';$('marketInfo').after(mount);}const rows=pool().filter(l=>l.id===g.id);mount.innerHTML=rows.length?'<h3>Add to betslip</h3><div class="gd-match-moneylines">'+rows.filter(l=>l.market==='moneyline').map(l=>marketButton({...l,modelPick:l.p>.5})).join('')+'</div>'+marketRows(g):'';}
 function open(id){const f=M.forecasts.find(f=>f.id===id);if(!f){selectedDay=E.day(allRows().find(g=>g.id===id)?.date||Date.now());home();return;} $('matchConference').value='all';fillGames();show(id);history.replaceState(null,'','#matchup/'+encodeURIComponent(id));tab('lab');document.querySelector('nav').scrollIntoView({behavior:'smooth',block:'start'});}
 function home(){history.replaceState(null,'','#picks');tab('slate');document.querySelector('nav').scrollIntoView({behavior:'smooth',block:'start'});}
 function calendar(){
  const rows=allRows(),today=E.day(Date.now()),keys=E.dates(rows),counts=new Map();for(const g of rows){const k=E.day(g.date);counts.set(k,(counts.get(k)||0)+1);}
  if(!keys.includes(selectedDay))selectedDay=today;
  $('gdDates').innerHTML=keys.map(k=>{const d=new Date(k+'T12:00Z'),n=counts.get(k)||0;return `<button type="button" data-day="${k}" aria-pressed="${k===selectedDay}" class="gd-day ${k===selectedDay?'selected':''}"><small>${k===today?'TODAY':d.toLocaleDateString('en-US',{timeZone:'UTC',weekday:'short'}).toUpperCase()}</small><b>${d.getUTCDate()}</b><span>${d.toLocaleDateString('en-US',{timeZone:'UTC',month:'short'})} · ${n} games</span></button>`;}).join('');
  $('gdDayTitle').textContent=(selectedDay===today?'Today · ':'')+fullDay(selectedDay);
 }
 function scoreLogo(g,side){const id=String(g[side]),url=A?.logos.includes(id)?`assets/logos-small/${encodeURIComponent(id)}.webp`:g[side+'Logo'];return url?`<img src="${esc(url)}" alt="" loading="lazy" width="44" height="44">`:'';}
 function ticker(){
  const today=E.day(Date.now()),rows=LiveScores.games.filter(g=>E.day(g.date)===today||g.state==='in').sort((a,b)=>(a.state==='in'?0:a.done?2:1)-(b.state==='in'?0:b.done?2:1)||a.date.localeCompare(b.date));
  const label=document.querySelector('.gd-ticker-label small');if(label)label.textContent=LiveScores.stale?(rows.length?'Scores delayed':'Connecting to scores'):'Refreshes every 10 min';
  $('gdTickerRail').innerHTML=rows.length?rows.map(g=>`<button class="gd-tick ${g.state==='in'?'gd-tick-live':''}" data-tick="${esc(g.id)}" aria-label="${esc(g.awayName+' at '+g.homeName+', '+(LiveScores.stale?'Score update delayed':g.detail))}"><span class="gd-tick-top">${LiveScores.stale?'DELAYED':g.state==='in'?'LIVE':g.done?'FINAL':'UPCOMING'}<em>${esc(g.state==='pre'?time(g)+' ET':g.detail)}</em></span>${['away','home'].map(side=>`<span class="gd-tick-team">${scoreLogo(g,side)}<b>${esc(g[side+'Abbr']||g[side+'Name'])}</b><strong>${g[side+'Score']??'—'}</strong></span>`).join('')}<small>${g.state==='pre'?'Kickoff '+new Date(g.date).toLocaleDateString('en-US',{timeZone:'America/New_York',month:'short',day:'numeric'}):LiveScores.stale?'Last received score':'Actual score'}</small></button>`).join(''):`<div class="gd-score-empty">${LiveScores.failed?'Scores unavailable. Retrying automatically.':LiveScores.retrievedAt?'No games scheduled today.':'Loading today’s scores…'}</div>`;
 }
 // Logo-derived school hues, brightened for the dark pick strip.
 const schoolColors={"2426":"#b8aa81","2335":"#1257b8","183":"#e64b17","356":"#e66d17","2623":"#b81220","2306":"#7312b8","26":"#3782b8","2429":"#12b873","6":"#123cb8","245":"#b82012","55":"#e62817","16":"#12b88e","61":"#b8123c","324":"#12aab8","197":"#e66d17","333":"#b8123c","2005":"#1257b8","2711":"#b83c12","252":"#1257b8","12":"#123cb8","249":"#12b83c","239":"#37b882","2628":"#8237b8","41":"#1257b8","2649":"#e6b217","167":"#b8123c","2247":"#1257b8","265":"#b8123c","87":"#1257b8","2026":"#e6b217","2390":"#e66d17","295":"#1273b8","66":"#e6b217","2449":"#12b88e","2509":"#e6d4a1","2229":"#1257b8","103":"#b83742","130":"#e6b217","24":"#b82012","62":"#12b873","2572":"#e6b217","2636":"#1257b8","5":"#37b86d","309":"#b81220","242":"#1257b8","2440":"#1257b8","2459":"#b81220","2050":"#b8123c","59":"#b8a15c","52":"#b83757","2199":"#37b86d","96":"#123cb8","204":"#e64b17","338":"#e6b217","2534":"#e64b17","328":"#376db8","2032":"#e6174b","258":"#5c73b8","2084":"#1257b8","193":"#b8123c","68":"#123cb8","2309":"#1257b8","2393":"#1273b8","2653":"#b83742","99":"#6d37b8","254":"#b82012","251":"#b85737","349":"#e6d4a1","127":"#37b897","152":"#e62817","2433":"#b8123c","2633":"#e68f17","145":"#e61728","264":"#5712b8","48":"#1273b8","2132":"#e61728","84":"#b81220","277":"#1257b8","248":"#b81220","8":"#b83742","142":"#e6b217","275":"#b82012","2117":"#b81273","154":"#b9c6d4","344":"#b83757","2567":"#b82012","166":"#b81220","30":"#b83742","151":"#8237b8","2641":"#b81220","189":"#b85737","23":"#123cb8","326":"#b83742","259":"#b85c73","194":"#b8123c","97":"#b81220","2348":"#1257b8","2638":"#123cb8","2294":"#b9c6d4","38":"#e6c973","153":"#73b6e6","25":"#1257b8","228":"#e66d17","221":"#1257b8","2751":"#b8735c","77":"#5737b8","158":"#e61728","2439":"#e6174b","218":"#b8123c","58":"#12b88e","276":"#12b857","238":"#e6b673","113":"#b84237","195":"#37b882","9":"#e6b217","2579":"#b81220","2655":"#12b88e","150":"#1273b8","2305":"#1257b8","256":"#b8a15c","201":"#b82012","278":"#b8123c","290":"#1257b8","98":"#e64552","213":"#123cb8","36":"#12b857","57":"#37b86d","164":"#e61728","2006":"#1257b8","235":"#1257b8","2483":"#12b873","21":"#b81220","120":"#e61728","2226":"#1257b8","2":"#1257b8","135":"#b81257","202":"#123cb8","2116":"#b8a15c"};
 const schoolColor=team=>schoolColors[String(team)]||'#80f7da';
 function schoolBlock(g,side,historical){
  const team=g[side],art=logo(team)||`<span class="gd-logo-fallback">${esc(D.teams[team]?.abbr||name(team))}</span>`;
  return `<div class="gd-school">${art}<h3>${esc(name(team).toUpperCase())}</h3>${TeamRankings.cardRanks(team,historical)}</div>`;
 }
 function pickCell(g,market,selection,active){
  const label={moneyline:'MONEYLINE',spread:'SPREAD',total:'TOTAL'}[market];
  const team=selection?.team,side=selection?.side?.toLowerCase();
  const l=selection?legFor(g.id,team,market,side):null;
  // A displayed line must match the actual saved offer before it can enter a slip.
  const can=active&&l&&(market==='moneyline'?l.odds===selection.odds:l.line===selection.line);
  const hasValue=selection&&(market==='moneyline'?Number.isFinite(selection.odds):Number.isFinite(selection.line));
  const value=!hasValue?'—':market==='moneyline'?signed(selection.odds):market==='spread'?signed(selection.line):(side==='over'?'O ':'U ')+selection.line;
  const color=schoolColor(team),style=market==='total'?`--pick-color:${schoolColor(g.away)};--pick-second:${schoolColor(g.home)}`:`--pick-color:${color};--pick-second:${color}`;
  const description=selection?(market==='total'?(side==='over'?'Over ':'Under ')+selection.line:name(team)+' '+(market==='moneyline'?'moneyline ':'spread ')+value):'No pick';
  const attrs=can?`data-add-game="${esc(g.id)}" data-add-team="${esc(l.team)}" data-market="${market}" data-side="${esc(l.side||'')}" aria-pressed="false"`:'';
  const unavailable=!hasValue?'No posted line':active?'Price unavailable':'Not available for the betslip';
  return `<button type="button" class="gd-pick-cell ${hasValue?'':'gd-pick-empty'}" style="${style}" ${attrs} ${can?'':'disabled'} aria-label="${esc(can?'Add '+legLabel(l)+' at '+signed(l.odds)+' to betslip':description+'. '+unavailable)}" title="${esc(can?legLabel(l)+' · '+signed(l.odds):unavailable)}"><small>${label}</small><span class="gd-pick-value">${team&&market!=='total'?logo(team):''}<b>${value}</b></span></button>`;
 }
 function tile(g,featuredPick=null){
  const upcoming=g.f&&!g.done&&!/POSTPONED|CANCEL/.test(g.status||'')&&Date.parse(g.date)>Date.now(),q=upcoming?forecast(g.f):null,s=g.savedPick?StartedGames.selections(g):null;
  const m=meta(g),o=typeof parlayOdds==='undefined'?null:parlayOdds?.games[g.id],readyQuote=upcoming&&Seabiscuit.eligibleQuote(o,g);
  const active=upcoming&&!DartHealth.health(M).stale&&!g.f.reviewRequired,pick=featuredPick?.team||(q?(q.margin===0?null:q.p>.5?g.home:g.away):s?.winner);
  const price=readyQuote&&pick?o[(pick===g.home?'home':'away')+'Moneyline']:null;
  const homeSpread=readyQuote&&Number.isFinite(o.homeSpread)?o.homeSpread:m.homeSpread,overUnder=readyQuote&&Number.isFinite(o.total)?o.total:m.overUnder;
  const spread=q&&Number.isFinite(homeSpread)?(Math.abs(q.margin+homeSpread)<1e-9?null:{team:q.margin+homeSpread>0?g.home:g.away,line:q.margin+homeSpread>0?homeSpread:-homeSpread}):s?.spread;
  const total=q&&Number.isFinite(overUnder)?(q.total===overUnder?null:{side:q.total>overUnder?'over':'under',line:overUnder}):s?.total;
  const kickoff=g.timeValid===false?'Time TBA':time(g)+' ET';
  const location=[g.venue,g.neutral?'Neutral site':null].filter(Boolean).join(' · ')||'Location TBA';
  const badge=featuredPick?`<div class="gd-pick-tag">${Seabiscuit.isSeabiscuit(featuredPick)?'🐎 SEABISCUIT PLAY':'UPSET PICK'}</div>`:!upcoming?`<div class="gd-pick-tag gd-saved-tag">${esc(status(g))} · SAVED PREGAME PICKS</div>`:'';
  return `<article class="gd-card gd-pick-card ${featuredPick?'gd-feature-card':''}">${badge}<div class="gd-school-matchup">${schoolBlock(g,'away',!upcoming)}<span class="gd-versus">VS</span>${schoolBlock(g,'home',!upcoming)}</div><div class="gd-game-info"><p><time datetime="${esc(g.date)}">${esc(kickoff)}</time><span aria-hidden="true"> / </span><span>${esc(channel(g))}</span></p><p class="gd-game-location">${esc(location)}</p></div><div class="gd-pick-strip" aria-label="Model picks">${pickCell(g,'moneyline',pick?{team:pick,odds:price}:null,active)}${pickCell(g,'spread',spread,active)}${pickCell(g,'total',total,active)}</div><div class="gd-card-footer">${upcoming?`<button data-open="${esc(g.id)}">Game analysis <span aria-hidden="true">↗</span></button>`:`<button data-live-game="${esc(g.id)}">View ${g.done?'final':'live'} score <span aria-hidden="true">↗</span></button>`}</div></article>`;
 }
 function renderScores(){
  if($('live')?.hidden)return;
  const rows=LiveScores.games.slice().sort((a,b)=>(a.state==='in'?0:a.done?2:1)-(b.state==='in'?0:b.done?2:1)||a.date.localeCompare(b.date));
  $('gdLiveNote').textContent=LiveScores.stale?'Score updates delayed. Showing last received scores.':'Scores refresh every 10 minutes.';
  $('gdLiveGrid').innerHTML=rows.length?rows.map(g=>`<article class="gd-card gd-live-card" id="live-${esc(g.id)}"><div class="gd-card-head"><b>${g.done?'FINAL':g.state==='in'?'LIVE':time(g)+' ET'}</b><span>${esc(g.detail||'')}</span></div>${['away','home'].map(side=>`<div class="gd-live-team">${scoreLogo(g,side)}<strong>${esc(g[side+'Name']||name(g[side]))}</strong><b>${g.state==='pre'?'—':g[side+'Score']??'—'}</b></div>`).join('')}</article>`).join(''):'<p>No live scores available yet.</p>';
 }
 function liveGame(id){tab('live');renderScores();document.getElementById('live-'+id)?.scrollIntoView({behavior:'smooth',block:'center'});}
 function lens(id){const f=M.forecasts.find(f=>f.id===id);if(!f)return;lensId=id;const g=game(f),q=forecast(f);$('gdLens').hidden=false;
  $('gdLens').innerHTML=`<div class="gd-panel-head"><div><span class="eyebrow">SCORE EXPLORER</span><h2>${esc(name(g.away))} <span>at</span> ${esc(name(g.home))}</h2></div><button data-close-lens aria-label="Close score explorer">×</button></div><div class="gd-lens-layout"><div class="gd-orbit"><svg viewBox="0 0 260 260" role="img" aria-label="Two team win chances"><circle class="gd-orbit-grid" cx="130" cy="130" r="117"/><circle class="gd-orbit-grid" cx="130" cy="130" r="91"/><circle class="gd-orbit-grid" cx="130" cy="130" r="66"/><path d="M0 130h260M130 0v260" class="gd-orbit-grid"/><circle class="gd-orbit-base" cx="130" cy="130" r="103"/><circle id="gdOrbitArc" cx="130" cy="130" r="103" pathLength="100" transform="rotate(-90 130 130)"/></svg><div class="gd-orbit-core"><small id="gdOrbitLabel"></small><strong id="gdOrbitPct"></strong><span>MODEL ESTIMATE</span></div></div><div class="gd-lens-controls"><div class="gd-lens-teams">${logo(g.away)}<b>${q.a} <span>–</span> ${q.h}</b>${logo(g.home)}</div><p class="gd-muted">Projected score</p><label for="gdMargin">Move the line. See how the chance changes.</label><input id="gdMargin" type="range" min="-35" max="35" step="0.5" value="0"><div class="gd-slider-labels"><span>${esc(D.teams[g.away].abbr)} by 35</span><span>${esc(D.teams[g.home].abbr)} by 35</span></div><h3 id="gdLensReadout" aria-live="polite"></h3><p class="gd-muted">Explores the forecast’s range. Does not change the pick.</p><button data-open="${esc(id)}" class="gd-primary">Full matchup ↗</button></div></div>`;
  const update=()=>{const n=Number($('gdMargin').value),p=n<0?cdf((n-q.margin)/f.coreSd):1-cdf((n-q.margin)/f.coreSd),team=n<0?g.away:g.home;$('gdOrbitArc').style.strokeDasharray=`${p*100} 100`;$('gdOrbitLabel').textContent=D.teams[team]?.abbr||name(team);$('gdOrbitPct').textContent=pct(p);$('gdLensReadout').textContent=`${pct(p)} chance ${name(team)} ${n===0?'wins outright':'wins by more than '+Math.abs(n)+' points'}.`;};$('gdMargin').oninput=update;update();$('gdLens').scrollIntoView({behavior:'smooth',block:'start'});
 }
 function stamp(t){return new Date(t).toLocaleString('en-US',{timeZone:'America/New_York',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})+' ET';}
 function reason(f,team){if(!f||!team)return 'No supporting contribution is available.';const g=game(f),direction=team===g.home?1:-1;
 const d=[...(f.coreContributions||[])].filter(x=>x.points*direction>0).sort((a,b)=>Math.abs(b.points)-Math.abs(a.points))[0];
 const labels={'Elo difference':'Stronger results against previous opponents','Net success-rate difference':'A better ability to keep drives moving','Scoring margin difference':'A stronger scoring record','Home field':'Home-field advantage','Explosive-rate difference':'More big-play potential','Yards/game difference':'A stronger yardage advantage','Scoring environment':'The scoring matchup'};
 return d?`${labels[d.name]||d.name} moves the forecast ${Math.abs(d.points)<1?'less than 1':'about '+Math.round(Math.abs(d.points))} point${Math.round(Math.abs(d.points))===1?'':'s'} toward ${name(team)}.`:'The forecast has no positive team-specific contribution to explain.';
 }
 function featured(){
 const today=E.day(Date.now()),todayGames=allRows().filter(g=>E.day(g.date)===today),next=allRows().find(g=>E.day(g.date)>today&&!g.done),day=todayGames.some(g=>Date.parse(g.date)>Date.now())?today:next?E.day(next.date):today;
 const candidates=Seabiscuit.picks(pCandidates(pWeek(day+'T12:00Z')).filter(r=>E.day(r.g.date)===day));
